<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Retrieve Resume</title><link rel="stylesheet" href="<?= base_url('assets/css/resume-maker.css') ?>"><?= view('partials/adsense_head') ?></head><body><main class="shell narrow"><a class="back" href="<?= site_url('/') ?>">← Back</a><div class="panel"><h1>Retrieve your resume</h1><p>Enter the same full name, date of birth, and email used when you saved it.</p><?php if($error): ?><div class="alert alert-error" role="alert"><?= esc($error) ?></div><?php endif ?><form method="post" action="<?= site_url('resume/retrieve') ?>" class="js-validate" novalidate><div class="field"><label for="r_name">Full Name</label><input id="r_name" required name="full_name" autocomplete="name" data-rule="name" value="<?= esc((string)service('request')->getPost('full_name')) ?>"><small class="field-msg" aria-live="polite"></small></div><div class="field"><label for="r_dob">Date of Birth</label><input id="r_dob" required type="date" name="date_of_birth" data-rule="dob" value="<?= esc((string)service('request')->getPost('date_of_birth')) ?>"><small class="field-msg" aria-live="polite"></small></div><div class="field"><label for="r_email">Email</label><input id="r_email" required type="email" name="email" autocomplete="email" data-rule="email" value="<?= esc((string)service('request')->getPost('email')) ?>"><small class="field-msg" aria-live="polite"></small></div><button class="btn" type="submit">Retrieve Resume</button></form></div><?= view('partials/ad', ['slot' => 'slotRetrieve']) ?></main><script src="<?= base_url('assets/js/resume-maker.js') ?>"></script></body></html>
